    "source": "function block_040591_adl(cpu) {\n  // 0x040591  01 01 00 00      ld bc, 0x000001\n  cpu.bc = 0x000001;\n  // 0x040595  c5               push bc\n  cpu.push(cpu.bc);\n  // 0x040596  cd 59 c1 04      call 0x04c159\n  cpu.call(0x04c159);\n  // 0x04059a  c1               pop bc\n  cpu.bc = cpu.pop();\n  // 0x04059b  cd 3b c3 04      call 0x04c33b\n  cpu.call(0x04c33b);\n  // 0x04059f  cd 06 bd 04      call 0x04bd06\n  cpu.call(0x04bd06);\n  // 0x0405a3  ed 38 0c         in0 a, (0x0c)\n  cpu.a = cpu.ioReadPage0(0x0c);\n  // 0x0405a6  cb d7            set 2, a\n  cpu.a |= 0x04;\n  // 0x0405a8  ed 39 0c         out0 (0x0c), a\n  cpu.ioWritePage0(0x0c, cpu.a);\n  // 0x0405ab  3e 09            ld a, 0x09\n  cpu.a = 0x09;\n  // 0x0405ad  32 00 00 f8      ld (0xf80000), a\n  cpu.write8(0xf80000, cpu.a);\n  // 0x0405b1  3a 0c 00 f9      ld a, (0xf9000c)\n  cpu.a = cpu.read8(0xf9000c);\n  // 0x0405b5  cb f7            set 6, a\n  cpu.a |= 0x40;\n  // 0x0405b7  32 0c 00 f9      ld (0xf9000c), a\n  cpu.write8(0xf9000c, cpu.a);\n  // 0x0405bb  f3               di\n  cpu.iff1 = 0;\n  cpu.iff2 = 0;\n  // 0x0405bc  cd 9c 03 00      call 0x00039c\n  cpu.call(0x00039c);\n  // 0x0405c0  40 01 00 a0      ld.sis bc, 0xa000\n  cpu.bc = 0xa000;\n  // 0x0405c4  af               xor a\n  cpu.a = 0;\n  cpu.updateLogicFlags(cpu.a);\n  // 0x0405c5  ed 79            out (c), a\n  cpu.ioWrite(cpu.c, cpu.a);\n  // 0x0405c7  78               ld a, b\n  cpu.a = cpu.b;\n  // 0x0405c8  fe a0            cp 0xa0\n  cpu.compare(cpu.a, 0xa0);\n  // 0x0405ca  28 01            jr z, 0x0405cd\n  if (cpu.checkCondition('z')) return 0x0405cd;\n  return 0x0405cc;\n}"
