    "source": "function block_001e1b_adl(cpu) {\n  // 0x001e1b  eb               ex de, hl\n  {\n    const temp = cpu.de;\n    cpu.de = cpu.hl;\n    cpu.hl = temp;\n  }\n  // 0x001e1c  11 01 00 3f      ld de, 0x3f0001\n  cpu.de = 0x3f0001;\n  // 0x001e20  b7               or a\n  cpu.updateLogicFlags(cpu.a);\n  // 0x001e21  ed 52            sbc hl, de\n  cpu.hl = cpu.subtractWithBorrowWord(cpu.hl, cpu.de);\n  // 0x001e23  dd 2f            cpl\n  cpu.a = (~cpu.a) & 0xff;\n  // 0x001e25  fd 3e ec         ld a, 0xec\n  cpu.a = 0xec;\n  // 0x001e28  11 00 00 3f      ld de, 0x3f0000\n  cpu.de = 0x3f0000;\n  // 0x001e2c  cd 94 1d 00      call 0x001d94\n  cpu.call(0x001d94);\n  // 0x001e30  21 00 00 3b      ld hl, 0x3b0000\n  cpu.hl = 0x3b0000;\n  // 0x001e34  cd 4d 0e 00      call 0x000e4d\n  cpu.call(0x000e4d);\n  // 0x001e38  3e ee            ld a, 0xee\n  cpu.a = 0xee;\n  // 0x001e3a  11 00 00 3b      ld de, 0x3b0000\n  cpu.de = 0x3b0000;\n  // 0x001e3e  cd 94 1d 00      call 0x001d94\n  cpu.call(0x001d94);\n  // 0x001e42  dd 07            rlca\n  cpu.a = cpu.rotateLeftCircular(cpu.a);\n  // 0x001e44  fd 11 01 00 3b   ld de, 0x3b0001\n  cpu.de = 0x3b0001;\n  // 0x001e49  21 01 00 3f      ld hl, 0x3f0001\n  cpu.hl = 0x3f0001;\n  // 0x001e4d  cd 2f 1d 00      call 0x001d2f\n  cpu.call(0x001d2f);\n  // 0x001e51  3e ec            ld a, 0xec\n  cpu.a = 0xec;\n  // 0x001e53  11 00 00 3b      ld de, 0x3b0000\n  cpu.de = 0x3b0000;\n  // 0x001e57  cd 94 1d 00      call 0x001d94\n  cpu.call(0x001d94);\n  // 0x001e5b  21 00 00 3f      ld hl, 0x3f0000\n  cpu.hl = 0x3f0000;\n  // 0x001e5f  cd 4d 0e 00      call 0x000e4d\n  cpu.call(0x000e4d);\n  // 0x001e63  dd f9            ld sp, ix\n  cpu.sp = cpu.ix;\n  // 0x001e65  dd e1            pop ix\n  cpu.ix = cpu.pop();\n  // 0x001e67  c9               ret\n  return cpu.popReturn();\n}"
