    "source": "function block_012e18_adl(cpu) {\n  // 0x012e18  01 00 00 00      ld bc, 0x000000\n  cpu.bc = 0x000000;\n  // 0x012e1c  c5               push bc\n  cpu.push(cpu.bc);\n  // 0x012e1d  cd 9d 74 00      call 0x00749d\n  cpu.call(0x00749d);\n  // 0x012e21  c1               pop bc\n  cpu.bc = cpu.pop();\n  // 0x012e22  40 01 14 30      ld.sis bc, 0x3014\n  cpu.bc = 0x3014;\n  // 0x012e26  ed 78            in a, (c)\n  cpu.a = cpu.ioRead(cpu.c);\n  // 0x012e28  dd 77 ff         ld (ix+0xff), a\n  cpu.writeIndexed8('ix', +0xff, cpu.a);\n  // 0x012e2b  dd 7e ff         ld a, (ix+0xff)\n  cpu.a = cpu.readIndexed8('ix', +0xff);\n  // 0x012e2e  e6 3f            and 0x3f\n  cpu.a &= 0x3f;\n  cpu.updateLogicFlags(cpu.a);\n  // 0x012e30  dd 77 ff         ld (ix+0xff), a\n  cpu.writeIndexed8('ix', +0xff, cpu.a);\n  // 0x012e33  dd 4e ff         ld c, (ix+0xff)\n  cpu.c = cpu.readIndexed8('ix', +0xff);\n  // 0x012e36  06 00            ld b, 0x00\n  cpu.b = 0x00;\n  // 0x012e38  c5               push bc\n  cpu.push(cpu.bc);\n  // 0x012e39  cd e0 74 00      call 0x0074e0\n  cpu.call(0x0074e0);\n  // 0x012e3d  c1               pop bc\n  cpu.bc = cpu.pop();\n  // 0x012e3e  01 80 00 00      ld bc, 0x000080\n  cpu.bc = 0x000080;\n  // 0x012e42  c5               push bc\n  cpu.push(cpu.bc);\n  // 0x012e43  cd 2d 32 01      call 0x01322d\n  cpu.call(0x01322d);\n  // 0x012e47  c1               pop bc\n  cpu.bc = cpu.pop();\n  // 0x012e48  dd f9            ld sp, ix\n  cpu.sp = cpu.ix;\n  // 0x012e4a  dd e1            pop ix\n  cpu.ix = cpu.pop();\n  // 0x012e4c  c9               ret\n  return cpu.popReturn();\n}"
